WITH reactions AS (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM documents WHERE collection_name = 'reactions') WHERE rn = 1 AND deleted = 0) d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM doc_groups WHERE group_id IN ('api.localhost/groups/users/c42-c000000/followers', 'api.localhost/groups/users/c42-c000001/followers', 'api.localhost/groups/users/c42-c000002/followers', 'api.localhost/groups/users/c42-c000003/followers', 'api.localhost/groups/users/c42-c000004/followers', 'api.localhost/groups/users/c42-c000005/followers', 'api.localhost/groups/users/c42-c000006/followers', 'api.localhost/groups/users/c42-c000007/followers', 'api.localhost/groups/users/c42-c000008/followers', 'api.localhost/groups/users/c42-c000009/followers', 'api.localhost/groups/users/c42-c000010/followers', 'api.localhost/groups/users/c42-c000011/followers', 'api.localhost/groups/users/c42-c000012/followers', 'api.localhost/groups/users/c42-c000013/followers', 'api.localhost/groups/users/c42-c000014/followers', 'api.localhost/groups/users/c42-c000015/followers', 'api.localhost/groups/users/c42-c000016/followers', 'api.localhost/groups/users/c42-c000017/followers', 'api.localhost/groups/users/c42-c000018/followers', 'api.localhost/groups/users/c42-c000019/followers', 'api.localhost/groups/web10/discover')) WHERE rn = 1 AND deleted = 0) dg ON d.doc_id = dg.doc_id WHERE d.author_key NOT IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND (d.author_key, dg.group_id) NOT IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'c42-reader') AND NOT (d.author_key != 'c42-reader' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND (d.doc_id, dg.group_id) NOT IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0) AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)) SELECT ref_value, countIf(JSONExtractString(body, 'type') = 'like') AS like_count, countIf(JSONExtractString(body, 'type') = 'dislike') AS dislike_count FROM reactions WHERE ref_value IN ('c42-doc-0', 'c42-doc-1', 'c42-doc-2', 'c42-doc-3', 'c42-doc-4', 'c42-doc-5', 'c42-doc-6', 'c42-doc-7', 'c42-doc-8', 'c42-doc-9', 'c42-doc-10', 'c42-doc-11', 'c42-doc-12', 'c42-doc-13', 'c42-doc-14', 'c42-doc-15', 'c42-doc-16', 'c42-doc-17', 'c42-doc-18', 'c42-doc-19') GROUP BY ref_value LIMIT 1000
